WITH base AS (SELECT *, CEIL(salary) AS salary_whole FROM employees WHERE hire_date >= DATE '2024-03-20' AND level IS NOT NULL AND YEAR(hire_date) >= 2025) SELECT *, AVG(salary_whole) OVER (ORDER BY salary, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS salary_whole_avg_6, LAG(salary, 2) OVER (PARTITION BY manager_id ORDER BY salary_whole, id) AS prev_salary, SUM(salary_whole) OVER (PARTITION BY job_title, dept_id ORDER BY salary_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary_whole FROM base
